<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'

const voiceStore = useVoiceStore()

/** The real SVC groups, shared with the mod, instead of a local dummy list. */
const channels = computed(() => voiceStore.groups)
const newChannelName = ref('')
const newGroupType = ref('normal')
const newGroupPersistent = ref(false)
const showCreateModal = ref(false)
const isCreating = ref(false)
const createError = ref<string | null>(null)

const currentChannelId = computed(() => voiceStore.state.currentChannel)

/** The three SVC group types, labelled the way the mod does. */
const TYPE_LABELS: Record<string, string> = {
  normal: 'Normal',
  open: 'Offen',
  isolated: 'Isoliert',
}

function typeLabel(type: string): string {
  // Unknown values fall back to a readable name, never to a Java class name.
  const known = TYPE_LABELS[type]
  if (known) return known
  return type.includes('.') || type.includes('@') ? 'Normal' : type
}

onMounted(() => voiceStore.requestGroupList())

function selectChannel(channelId: string) {
  voiceStore.joinChannel(channelId)
}

async function createChannel() {
  if (!newChannelName.value.trim()) return
  
  createError.value = null
  isCreating.value = true
  
  try {
    const created = await voiceStore.createChannel({
      name: newChannelName.value.trim(),
      type: newGroupType.value,
      persistent: newGroupPersistent.value,
    })
    if (!created) {
      createError.value = 'Gruppe konnte nicht erstellt werden'
      isCreating.value = false
      return
    }
    newChannelName.value = ''
    newGroupType.value = 'normal'
    newGroupPersistent.value = false
    showCreateModal.value = false
  } catch (err) {
    createError.value = err instanceof Error ? err.message : 'Fehler beim Erstellen'
  } finally {
    isCreating.value = false
  }
}

function deleteChannel(channelId: string) {
  if (confirm('Diesen Kanal wirklich löschen?')) {
    voiceStore.deleteChannel(channelId)
  }
}
</script>

<template>
  <div class="channel-list">
    <div class="channel-header">
      <h3>Gruppen</h3>
      <button @click="showCreateModal = true" class="btn btn-icon btn-sm" aria-label="Neue Gruppe erstellen">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <line x1="12" y1="5" x2="12" y2="19" />
          <line x1="5" y1="12" x2="19" y2="12" />
        </svg>
      </button>
    </div>
    
    <ul class="channels" role="listbox" aria-label="Verfügbare Gruppen">
      <li v-for="channel in channels" :key="channel.id" class="channel-item">
        <button
          @click="selectChannel(channel.id)"
          class="channel-btn"
          :class="{ active: currentChannelId === channel.id }"
          :aria-selected="currentChannelId === channel.id"
          role="option"
        >
          <span class="channel-icon">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M12 19l7-7 3 3-7 7-3-3z" />
              <path d="M18 13l-7-7-3 3 7 7 3-3z" />
            </svg>
          </span>
          <span class="channel-name" :title="channel.name">{{ channel.name }}</span>
          <span class="channel-meta">
            {{ channel.participants }} {{ channel.participants === 1 ? 'Person' : 'Personen' }}
          </span>
          <span class="private-badge" :title="`Typ: ${channel.type}`">
            {{ typeLabel(channel.type) }}
          </span>
          <span v-if="channel.persistent" class="private-badge" title="Bleibt nach dem Neustart erhalten">
            Persistent
          </span>
        </button>
        <button
          v-if="currentChannelId !== channel.id"
          @click.stop="deleteChannel(channel.id)"
          class="btn btn-icon btn-xs btn-danger"
          aria-label="Gruppe löschen"
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <polyline points="3 6 5 6 21 6" />
            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
          </svg>
        </button>
      </li>
      
      <li v-if="channels.length === 0" class="empty-state">
        <p>Keine Gruppen vorhanden</p>
        <button @click="showCreateModal = true" class="btn btn-primary btn-sm">
          Erste Gruppe erstellen
        </button>
      </li>
    </ul>
    
    <div v-if="showCreateModal" class="modal-overlay" @click.self="showCreateModal = false">
      <div class="modal" role="dialog" aria-modal="true" aria-labelledby="create-channel-title">
        <h3 id="create-channel-title">Neue Gruppe erstellen</h3>
        <div v-if="createError" class="error">{{ createError }}</div>
        <div class="form-group">
          <label for="channelName">Gruppenname</label>
          <input
            id="channelName"
            v-model="newChannelName"
            type="text"
            maxlength="32"
            @keyup.enter="createChannel"
            placeholder="z. B. Allgemein, Gaming, Besprechung"
            autofocus
          />
        </div>
        <div class="form-group">
          <label for="groupType">Typ</label>
          <select id="groupType" v-model="newGroupType" class="setting-select">
            <option value="normal">Normal – alle hören sich untereinander</option>
            <option value="open">Offen – jeder kann beitreten</option>
            <option value="isolated">Isoliert – nur wer beitritt hört zu</option>
          </select>
        </div>
        <div class="form-group">
          <label class="checkbox-label">
            <input v-model="newGroupPersistent" type="checkbox" />
            Persistent – bleibt nach einem Neustart erhalten
          </label>
        </div>
        <div class="modal-actions">
          <button @click="showCreateModal = false" class="btn btn-secondary">Abbrechen</button>
          <button @click="createChannel" class="btn btn-primary" :disabled="isCreating || !newChannelName.trim()">
            {{ isCreating ? 'Erstelle...' : 'Erstellen' }}
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

